{"command":"cd /testbed && python -c "
from mpmath import mp
import random
random.seed(1)
mism = 0
tests = []
for _ in range(20000):
    v = random.uniform(0, 1) * 10**random.randint(-10, 10)
    tests.append(v)
for v in tests:
    for spec in ['.0g','.1g','.2g','.3g','.4g','.5g','.6g','.7g','g','G','e','E','f','F','b','B']:
        c = format(v, spec)
        m = format(mp.mpf(v), spec)
        if c != m:
            mism += 1
            if mism < 20:
                print('MISMATCH', v, spec, repr(c), repr(m))
print('total mismatches', mism)
""}

